create function public.cineo_record_exposure(actor uuid,tid uuid,choice integer,event text) returns jsonb language plpgsql security invoker set search_path='' as $$begin
 if choice not in(0,1) or event not in('seen','started') then raise exception 'Exposição inválida';end if;
 insert into public.cineo_ab_exposures(test_id,user_id,variant,seen,started) values(tid,actor,choice,event='seen',event='started') on conflict(test_id,user_id,day) do update set seen=public.cineo_ab_exposures.seen or excluded.seen,started=public.cineo_ab_exposures.started or excluded.started;
 return jsonb_build_object('ok',true);end$$;
create function public.cineo_experiment_results(tid uuid) returns jsonb language sql stable security invoker set search_path='' as $$select coalesce(jsonb_agg(x),'[]') from(select v variant,count(e.id) filter(where e.seen) impressions,count(e.id) filter(where e.seen and e.started) starts,count(e.id) filter(where e.qualified) qualified_views from generate_series(0,1)v left join public.cineo_ab_exposures e on e.test_id=tid and e.variant=v group by v order by v)x$$;
create function public.cineo_reviewable_months() returns jsonb language sql stable security invoker set search_path='' as $$select coalesce(jsonb_agg(x order by month desc),'[]') from(select q.creator_id,date_trunc('month',q.day)::date as month,count(*) views,floor(sum(q.rate_cents_per_thousand)/1000.0) gross_cents,max(p.name) creator_name from public.cineo_qualified_views q left join public.cineo_profiles p on p.user_id=q.creator_id where q.day<date_trunc('month',now() at time zone 'America/Sao_Paulo')::date and not exists(select 1 from public.cineo_monthly_settlements s where s.creator_id=q.creator_id and s.month=date_trunc('month',q.day)::date) group by q.creator_id,date_trunc('month',q.day)::date order by 2 desc limit 100)x$$;
revoke all on function public.cineo_record_exposure(uuid,uuid,integer,text),public.cineo_experiment_results(uuid),public.cineo_reviewable_months() from public,anon,authenticated;
grant execute on function public.cineo_record_exposure(uuid,uuid,integer,text),public.cineo_experiment_results(uuid),public.cineo_reviewable_months() to service_role;
